import{_ as o,C as s,o as t,c as r,a6 as n,E as i}from"./chunks/framework.CKIbuWFA.js";const g=JSON.parse('{"title":"Encontrar preferencias y controles de teclado","description":"","frontmatter":{"title":"Encontrar preferencias y controles de teclado","docId":"user.preferences.index","translationKey":"user.preferences.index","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6790ab7171a90bda1df882c0f88626a5875da68bf4f624968b0e54815842030f","translationRevision":"557ac7d37d8f3a516e9b48f5722120d36bfdb33c1aab8b8fce56191e4cfc9ad3","order":10},"headers":[],"relativePath":"es/user/preferences/index.md","filePath":"es/user/preferences/index.md","lastUpdated":1794611623000}'),c={name:"es/user/preferences/index.md"};function d(l,e,u,p,f,m){const a=s("DemoFrame");return t(),r("div",null,[e[0]||(e[0]=n('<h1 id="find-preferences-and-keyboard-controls" tabindex="-1">Encontrar preferencias y controles de teclado <a class="header-anchor" href="#find-preferences-and-keyboard-controls" aria-label="Permalink to &quot;Encontrar preferencias y controles de teclado {#find-preferences-and-keyboard-controls}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Configura el idioma, localiza el área de ajustes correcta y utiliza cómodamente los controles de teclado admitidos. Necesitas la ventana de escritorio abierta; Internet solo es necesario para el servicio que estés configurando.</p><h2 id="find-the-relevant-setting" tabindex="-1">Localizar cada ajuste <a class="header-anchor" href="#find-the-relevant-setting" aria-label="Permalink to &quot;Localizar cada ajuste {#find-the-relevant-setting}&quot;">​</a></h2><ol><li>Abre <strong>Settings → General</strong> para elegir el idioma de interfaz. Las opciones actuales son inglés (<code>en</code>), español (<code>es</code>), portugués (<code>pt</code>), francés (<code>fr</code>), chino simplificado (<code>zh</code>) y japonés (<code>ja</code>). Esta selección no modifica identificadores de eventos de TikTok ni nombres de API de plugins.</li><li>Revisa los controles de actualización de General: canal, comprobaciones automáticas, notificaciones y consulta manual cuando sea compatible. Las comprobaciones automáticas son opcionales. La disponibilidad de actualizaciones firmadas depende de la configuración de firma publicada con la compilación.</li><li>Usa <strong>Account</strong> para identidad de Cloud y diagnósticos. <strong>Collaboration</strong> configura acceso del propietario; <strong>Teams</strong> aparece cuando el host anuncia esa capacidad.</li><li>Abre <strong>Plugins</strong> para preferencias generales de plugins y los paneles Settings/Connection de cada uno. Sus credenciales de servicio no pertenecen a los ajustes generales.</li><li>Abre <strong>Automations → Variables</strong> para valores compartidos, <strong>Points</strong> para reglas de obtención y <strong>Overlays</strong> para diseños. Estas superficies están junto a las funciones que configuran.</li></ol><p>La instalación automática es experimental y está desactivada por los controles de compilación del flujo de publicación actual. La opción de consultas automáticas no promete instalar automáticamente. Sigue el <a href="./../updates.html">proceso de actualización</a> y crea una <a href="./backups.html">copia</a> antes de cambiar de versión.</p><h2 id="use-supported-keyboard-controls" tabindex="-1">Utilizar el teclado <a class="header-anchor" href="#use-supported-keyboard-controls" aria-label="Permalink to &quot;Utilizar el teclado {#use-supported-keyboard-controls}&quot;">​</a></h2><p>Tab y Shift+Tab mueven el foco entre controles ordinarios; Enter/Espacio activan botones enfocados. En el inspector de diseños, Ctrl/Meta+Z deshace y Ctrl/Meta+Shift+Z o Ctrl/Meta+Y rehace. Los campos de texto conservan su propio deshacer. Son atajos del editor, no disparadores globales de automatización.</p><p>Escape cierra el menú lateral estrecho si otro control no lo ha consumido. Los diálogos y editores pueden manejarlo primero, incluida una confirmación por cambios pendientes. Las automatizaciones con teclas globales requieren un plugin compatible y las capacidades anunciadas por su entorno.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Resultado esperado, estado y recuperación <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Resultado esperado, estado y recuperación {#expected-result-status-and-recovery}&quot;">​</a></h2><p>Estos ajustes e interacciones locales están disponibles; no se acredita aceptación completa de accesibilidad ni de todas las plataformas. Prefiere botones etiquetados, tamaños legibles y pausar el feed si su movimiento distrae. Si falta un ajuste, comprueba su página y la capacidad del host antes de borrar datos. Consulta <a href="./troubleshooting.html">solución de problemas</a> y las <a href="./faq.html">preguntas frecuentes</a>.</p>',11)),i(a,{scenario:"settings",locale:"es",title:"Demo de settings"})])}const h=o(c,[["render",d]]);export{g as __pageData,h as default};
